@GameTestHolder("kingdom_smp_bounty_tests") @PrefixGameTestTemplate(false)
public final class BountyRuntimeTests {
 private static long requests;
 @GameTest(template="empty",timeoutTicks=9000)
 public static void actualBountyConstructionAndCommunity(GameTestHelper h)throws Exception{BankRuntimeTests.completeBankLoop(h,()->guard(h,()->build(h)));}
 private static void build(GameTestHelper h)throws Exception{
  var level=h.getLevel();var server=level.getServer();var hall=ConstructionService.lodge(server);var p=server.getPlayerList().getPlayer(hall.owner());var bank=ConstructionService.store(server).projects().stream().filter(v->v.blueprint().equals(RoyalBankBlueprint.ID)).findFirst().orElseThrow();near(p,level.getEntity(bank.npc()));CommerceService.openResident(p,(com.mohymods.kingdomsmp.npc.ReeveEntity)level.getEntity(bank.npc()));
  boolean refused=false;try{CommerceService.handle(p,new CommerceRequest(++requests,1,8,"bounty:kingdom_smp:community/grain",64,CommerceRequest.NONE));}catch(IllegalStateException expected){refused=expected.getMessage().contains("Bounty Hall");}h.assertTrue(refused,"Tier3 alone grants no Bounty service before its actual completed building");
  var purchase=review(p,0,RoyalBountyHallBlueprint.ID.toString(),1);confirm(p,purchase,0);var store=ConstructionService.store(server);var project=store.reward("market:"+RoyalBountyHallBlueprint.ID).orElseThrow();ConstructionService.select(p,project.id());var claim=ConstructionService.review(p,1);ConstructionService.confirm(p,claim.nonce(),2);h.assertTrue(p.getMainHandItem().is(KingdomBlueprints.BOUNTY.get()),"First buyer receives its distinct authenticated physical Bounty plan");
  var b=BlueprintRegistry.get(project.blueprint(),1);var site=hall.origin().offset(40,0,40);for(var pos:BlockPos.betweenClosed(site.offset(-3,-1,-4),site.offset(b.width()+3,-1,b.depth()+3)))level.setBlock(pos,Blocks.STONE.defaultBlockState(),18);
  for(int x=site.getX()>>4;x<=(site.getX()+b.width()-1)>>4;x++)for(int z=(site.getZ()-1)>>4;z<=(site.getZ()+b.depth()-1)>>4;z++){var pos=new BlockPos(x*16,site.getY(),z*16);ClaimRuntimeTests.ftbClaim(p,pos);ClaimRuntimeTests.opacClaim(level,p.getUUID(),pos);}
  p.moveTo(site.getX()-2,site.getY()+1,site.getZ());var preview=ConstructionService.preview(p,site,Rotation.CLOCKWISE_180);h.assertTrue(preview.denial().isEmpty(),"Rotated full hall site passes both actual claim APIs: "+preview.denial());var placement=ConstructionService.view(p,1,false,"");ConstructionService.confirm(p,placement.review(),4);var start=ConstructionService.review(p,7);ConstructionService.confirm(p,start.nonce(),8);var hut=BuilderHutSavedData.get(server).hut().orElseThrow();var aldric=level.getEntity(hut.npcId());var post=b.workPost(site,Rotation.CLOCKWISE_180);aldric.moveTo(post.getX()+.5,post.getY(),post.getZ()+.5);
  boolean[] done={false};int[] stalled={0},lastPlaced={-1};h.onEachTick(()->{if(done[0])return;guard(h,()->{for(int n=0;n<2&&store.get(project.id()).phase()==ConstructionStore.Phase.BUILDING;n++)ConstructionService.step(server,project.id());if(store.get(project.id()).phase()!=ConstructionStore.Phase.COMPLETE){int placed=store.get(project.id()).placed();if(placed==lastPlaced[0]&&++stalled[0]>80)throw new IllegalStateException("Bounty construction stalled at "+placed+"/"+b.blocks().size()+": "+ConstructionService.view(p,9,false,"").activity());if(placed!=lastPlaced[0]){lastPlaced[0]=placed;stalled[0]=0;}return;}done[0]=true;h.runAfterDelay(20,()->guard(h,()->deliver(h,p,store.get(project.id()))));});});
 }
 private static void deliver(GameTestHelper h,ServerPlayer p,ConstructionStore.Project project)throws Exception{
  var server=p.server;var level=p.serverLevel();h.assertTrue(ConstructionService.structureIntact(level,project),"Complete furnished Bounty Hall matches saved construction prefix");var b=BlueprintRegistry.get(project.blueprint(),1);for(var block:b.blocks(project.rotation())){var pos=project.origin().offset(block.offset());h.assertTrue(level.getBlockState(pos).canSurvive(level,pos),"Every real rotated Bounty furnishing is supported: "+pos);}
  var npc=level.getEntity(project.npc());h.assertTrue(npc instanceof com.mohymods.kingdomsmp.npc.ReeveEntity&&npc.getName().getString().equals("Garrick Thornfield"),"Exactly assigned permanent named Bounty Master spawns after verified completion");near(p,npc);CommerceService.openResident(p,(com.mohymods.kingdomsmp.npc.ReeveEntity)npc);
  var path=server.getWorldPath(LevelResource.ROOT).resolve("serverconfig/kingdomsmp-community-contracts.json");CommunityContractRules.get(server);Files.writeString(path,Files.readString(path).replace("\"goal\": 1024","\"goal\": 100"));CommunityContractRules.clear(server);var store=CommerceService.store(server);long week=ContractRules.period("weekly");String id="bounty:kingdom_smp:community/grain";
  p.getInventory().clearContent();p.getInventory().setItem(0,new ItemStack(Items.WHEAT,64));var stale=review(p,8,id,64);p.getInventory().getItem(0).shrink(1);boolean changed=false;try{confirm(p,stale,8);}catch(IllegalStateException expected){changed=true;}h.assertTrue(changed&&p.getInventory().getItem(0).getCount()==63&&store.communityProject("kingdom_smp:community/grain",week).isEmpty(),"Stale community inventory consumes and awards nothing");p.getInventory().setItem(0,new ItemStack(Items.WHEAT,64));var first=review(p,8,id,64);confirm(p,first,8);h.assertTrue(p.getInventory().getItem(0).isEmpty()&&store.communityProject("kingdom_smp:community/grain",week).orElseThrow().delivered()==64,"First actual64wheat batch saved with shared partial progress");long revision=store.revision();try{confirm(p,first,8);}catch(IllegalStateException expected){ }h.assertTrue(store.revision()==revision,"Replayed batch nonce cannot manufacture progress or funded reward");p.getInventory().setItem(0,new ItemStack(Items.WHEAT,64));var last=review(p,8,id,64);confirm(p,last,8);h.assertTrue(p.getInventory().getItem(0).getCount()==28&&store.communityProject("kingdom_smp:community/grain",week).orElseThrow().complete(),"Final native delivery accepts only remaining36; extra28wheat preserved");h.assertTrue(store.communitySpent(week)==100&&store.communityMasterProofs(p.getUUID())==0,"Exactly100coins funded; non-Farmer fixture gains no fake Master proof");
  var reopened=EconomyStore.open(server.getWorldPath(LevelResource.ROOT).resolve("data"));var saved=ConstructionStore.open(server.getWorldPath(LevelResource.ROOT).resolve("data")).get(project.id());h.assertTrue(saved.npc().equals(project.npc())&&saved.phase()==ConstructionStore.Phase.COMPLETE&&reopened.communityProject("kingdom_smp:community/grain",week).orElseThrow().complete(),"Bounty identity, construction and community completion reopen without duplication");CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("BOUNTY_ASSERTIONS_PASSED: real Tier3, first-buyer plan, both claims, rotated progressive Aldric hall, supported furniture, permanent Bounty Master, actual partial deliveries, stale/replay refusal, funded rewards and reopen");h.succeed();
 }
 private static CommerceView review(ServerPlayer p,int tab,String id,int quantity){var view=CommerceService.handle(p,new CommerceRequest(++requests,1,tab,id,quantity,CommerceRequest.NONE));if(!view.reviewing())throw new IllegalStateException("No review: "+view.notice());return view;}
 private static void confirm(ServerPlayer p,CommerceView view,int tab){CommerceService.handle(p,new CommerceRequest(++requests,2,tab,"",1,view.review()));}
 private static void near(ServerPlayer p,net.minecraft.world.entity.Entity npc){var level=p.serverLevel();for(var pos:BlockPos.betweenClosed(npc.blockPosition().offset(-2,0,-2),npc.blockPosition().offset(2,0,2))){if(!level.getBlockState(pos).isAir()||!level.getBlockState(pos.above()).isAir()||!level.getBlockState(pos.below()).isFaceSturdy(level,pos.below(),net.minecraft.core.Direction.UP))continue;p.moveTo(pos.getX()+.5,pos.getY(),pos.getZ()+.5);if(p.hasLineOfSight(npc)&&p.distanceToSqr(npc)<25)return;}throw new IllegalStateException("No valid nearby resident interaction position");}
 @FunctionalInterface private interface Step{void run()throws Exception;}
 private static void guard(GameTestHelper h,Step step){try{step.run();}catch(Exception e){h.runAfterDelay(1,()->h.fail(e.toString()));}}
}
